1349	+/// Collects every state the cubit emits for the duration of [act], since the
1350	+/// stack has no `bloc_test` pin — this drives [AuthCubit] through its public
1351	+/// API only (never the `@protected` `emit`), the same way any other
1352	+/// `flutter_bloc` consumer would.
1353	+Future<List<AuthState>> _emittedDuring(
1354	+  AuthCubit cubit,
1355	+  Future<void> Function() act,
1356	+) async {
1357	+  final emitted = <AuthState>[];
1358	+  final subscription = cubit.stream.listen(emitted.add);
1359	+  await act();
1360	+  // `submit()`'s awaited repository call resolves its mocked Future on a
1361	+  // microtask; `Future.delayed(Duration.zero)` only resumes once the whole
1362	+  // microtask queue (including the stream's event dispatch to our
1363	+  // listener) has drained, so this reliably waits for every emit `act()`
1364	+  // triggered before we stop listening.
1365	+  await Future<void>.delayed(Duration.zero);
1366	+  await subscription.cancel();
1367	+  return emitted;
1368	+}
